with valid_shipments as (select * from shipments where shipped_date < '2025-08-01' and cost >= 38 and delivered_date >= '2023-07-01'), summary as (select case when year(shipped_date) < 2024 then 'before_2024' when year(shipped_date) = 2024 then '2024' else 'after_2024' end as shipped_cohort, round((100 * sum(case when status = 'RETURNED' then 1 else 0 end)) / count(*), 1) as pct_returned, min(shipped_date) as first_shipped_date from valid_shipments group by case when year(shipped_date) < 2024 then 'before_2024' when year(shipped_date) = 2024 then '2024' else 'after_2024' end) select shipped_cohort, pct_returned, first_shipped_date from summary;
